package dev.pocketengine.features.plugins;

import static org.junit.Assert.*;
import android.app.Application;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.ui.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Set;
import java.util.UUID;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;

/** Actual native cleared SQL facts -> catalogue -> UI correlation -> separate native install.
 * Presentation tests do not claim Compose/device visual acceptance or mint approval from JSON. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class McpLocalInstallationPresentationTest {
    private static final McpLocalInstallationRules RULES=McpLocalInstallationRules.INSTANCE;
    private static JSONObject envelope(String request,JSONObject body)throws Exception{return new JSONObject().put("requestId",request).put("ok",true).put("result",new JSONObject(body.toString()));}
    private static String discover(McpLocalDiscoveryOwnerTest.Fixture x)throws Exception{String id=x.confirm(x.prepare()).getString("taskId");assertEquals("completed",x.finished(id).getString("status"));return id;}
    private static JSONObject catalogue(McpLocalDiscoveryOwnerTest.Fixture x,String task)throws Exception{return x.owner.mcp("readLocalMcpInstallCatalogue",new JSONObject().put("taskId",task));}
    private static final class View implements AutoCloseable {
        final McpLocalDiscoveryOwnerTest.Fixture x=new McpLocalDiscoveryOwnerTest.Fixture();final String task,catalogueRequest=UUID.randomUUID().toString(),request=UUID.randomUUID().toString();final JSONObject catalogue,snapshot,body,reply;final McpLocalInstallCatalogue frozenCatalogue;final McpLocalInstallPreparation preparation;final Set<String> selected=Set.of("lookup");final long now=System.currentTimeMillis();
        View()throws Exception{this(false);}
        View(boolean previous)throws Exception{if(previous)x.f.installEcho();task=discover(x);catalogue=catalogue(x,task);snapshot=x.owner.mcpSnapshot();frozenCatalogue=RULES.catalogue(catalogueRequest,task,envelope(catalogueRequest,catalogue));assertNotNull(catalogue.toString(),frozenCatalogue);JSONObject input=RULES.preparationPayload(frozenCatalogue,selected,snapshot);body=x.owner.mcp("prepareLocalMcpInstall",input);reply=envelope(request,body);preparation=new McpLocalInstallPreparation(request,frozenCatalogue.getDigest(),input.getJSONArray("tools").toString(),4);}
        McpLocalInstallReviewed frozen(){return RULES.freeze(preparation,frozenCatalogue,selected,4,snapshot,reply,System.currentTimeMillis());}
        public void close()throws Exception{x.close();}
    }
    @Test public void nativeCatalogueReadsOnlyOriginalClearedFactsAndCreatesNoReviewTaskOrProgram()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String task=discover(x);String before=x.f.runtime.query(x.ref(task)).json().getString("stderr");JSONObject body=catalogue(x,task);assertFalse(body.getBoolean("programStarted"));assertFalse(body.getBoolean("executionAuthorized"));assertFalse(body.getBoolean("installationAuthorized"));assertTrue(body.getBoolean("sourceRuntimeRevalidationRequired"));assertEquals(McpData.MAX_IMPORTED_TOOLS,body.getInt("maxImportedTools"));assertEquals(1,body.getJSONArray("tools").length());assertTrue(body.getJSONArray("tools").getJSONObject(0).getBoolean("supported"));assertFalse(body.has("argv"));assertFalse(body.toString().contains("--public-mode"));assertFalse(body.toString().contains("nativeJob"));assertEquals(before,x.f.runtime.query(x.ref(task)).json().getString("stderr"));assertEquals(1,x.f.tasks.list().length());assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void ordinaryAndUnconfirmedTasksCannotBecomeAReadOnlyInstallCatalogue()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String ordinary=x.f.tasks.createCapabilityTask("Not discovery","").getString("id");assertThrows(SecurityException.class,()->catalogue(x,ordinary));var confirmed=x.f.confirmed();x.f.tasks.beginOwnerMcpDiscoveryForOwner(confirmed,new RunControl());assertThrows(SecurityException.class,()->catalogue(x,confirmed.actionId()));assertThrows(IllegalArgumentException.class,()->x.f.plugins.handle("readLocalMcpInstallCatalogue",new JSONObject().put("taskId",ordinary)));confirmed.close();}}
    @Test public void catalogueCorrelationRequiresOriginalTaskSuccessfulRequestAndIntactDigest()throws Exception{try(View v=new View()){assertNull(RULES.catalogue("different",v.task,envelope(v.catalogueRequest,v.catalogue)));assertNull(RULES.catalogue(v.catalogueRequest,UUID.randomUUID().toString(),envelope(v.catalogueRequest,v.catalogue)));JSONObject bad=new JSONObject(v.catalogue.toString()).put("sourceDigest","0".repeat(64));assertNull(RULES.catalogue(v.catalogueRequest,v.task,envelope(v.catalogueRequest,bad)));assertNull(RULES.catalogue(v.catalogueRequest,v.task,envelope(v.catalogueRequest,v.catalogue).put("ok",false)));}}
    @Test public void catalogueAuthorityFlagsRemainFalseEvenWithARehashedChangedBody()throws Exception{try(View v=new View()){for(String field:new String[]{"programStarted","executionAuthorized","installationAuthorized"}){JSONObject body=new JSONObject(v.catalogue.toString());body.remove("catalogueDigest");body.put(field,true);body.put("catalogueDigest",McpInstallPreviewRules.digest(body));assertNull(field,RULES.catalogue(v.catalogueRequest,v.task,envelope(v.catalogueRequest,body)));}}}
    @Test public void nativeCatalogueKeepsAllSupportedAndUnsupportedRowsAndSelectionUsesOriginalImportLimit()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){JSONArray remote=new JSONArray();for(int i=0;i<McpData.MAX_IMPORTED_TOOLS+2;i++)remote.put(new JSONObject().put("name","tool_"+i).put("inputSchema",new JSONObject().put("type","object")));remote.put(new JSONObject().put("name","unsupported_oneOf").put("inputSchema",new JSONObject().put("type","object").put("oneOf",new JSONArray().put(new JSONObject()))));String old=McpLocalDiscoveryNativeTest.python(McpStdioClient.VERSION,"");String marker="  result={'tools':[{'name':'lookup','description':'untrusted own source','inputSchema':{'type':'object','properties':{}}}]}";assertTrue(old.contains(marker));String program=old.replace(marker,"  result=json.loads("+JSONObject.quote(new JSONObject().put("tools",remote).toString())+")");Files.write(x.f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(x.f.checkout).resolve("files/server.py"),program.getBytes(StandardCharsets.UTF_8));x.f.config.put("expectedSourceDigest",x.f.digest());String task=discover(x);JSONObject body=catalogue(x,task);assertEquals(McpData.MAX_IMPORTED_TOOLS+3,body.getJSONArray("tools").length());JSONObject unsupported=body.getJSONArray("tools").getJSONObject(remote.length()-1);assertFalse(unsupported.getBoolean("supported"));assertFalse(unsupported.getString("unsupportedReason").isBlank());String request=UUID.randomUUID().toString();var frozen=RULES.catalogue(request,task,envelope(request,body));assertNotNull(frozen);JSONObject snapshot=x.owner.mcpSnapshot();assertThrows(IllegalArgumentException.class,()->RULES.preparationPayload(frozen,Set.of("unsupported_oneOf"),snapshot));assertThrows(IllegalArgumentException.class,()->RULES.preparationPayload(frozen,Set.of("unknown"),snapshot));java.util.Set<String> selected=new java.util.HashSet<>();for(int i=0;i<McpData.MAX_IMPORTED_TOOLS;i++)selected.add("tool_"+i);assertEquals(McpData.MAX_IMPORTED_TOOLS,RULES.preparationPayload(frozen,selected,snapshot).getJSONArray("tools").length());selected.add("tool_"+McpData.MAX_IMPORTED_TOOLS);assertThrows(IllegalArgumentException.class,()->RULES.preparationPayload(frozen,selected,snapshot));assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());}}
    @Test public void actualNativeReviewCanProduceOnlyItsTwoOriginalConfirmationReferences()throws Exception{try(View v=new View()){var frozen=v.frozen();assertNotNull(v.body.toString(),frozen);JSONObject confirm=RULES.confirmationPayload(frozen,v.frozenCatalogue,v.selected,4,v.snapshot,v.reply,System.currentTimeMillis());assertEquals(2,confirm.length());assertEquals(v.body.getString("reviewId"),confirm.getString("reviewId"));assertEquals(v.body.getString("reviewDigest"),confirm.getString("reviewDigest"));assertFalse(confirm.has("approved"));assertFalse(confirm.has("tools"));assertFalse(confirm.has("configuration"));assertEquals(1,v.x.f.tasks.list().length());}}
    @Test public void editedSelectionRevisionOrDifferentCatalogueCannotReuseTheDisplayedReview()throws Exception{try(View v=new View()){var frozen=v.frozen();assertNull(RULES.current(frozen,v.frozenCatalogue,v.selected,5,v.snapshot,v.reply,System.currentTimeMillis()));assertNull(RULES.current(frozen,v.frozenCatalogue,Set.of(),4,v.snapshot,v.reply,System.currentTimeMillis()));var wrong=new McpLocalInstallPreparation(v.request,"0".repeat(64),v.preparation.getTools(),4);assertNull(RULES.freeze(wrong,v.frozenCatalogue,v.selected,4,v.snapshot,v.reply,System.currentTimeMillis()));assertNull(RULES.freeze(v.preparation,v.frozenCatalogue,v.selected,4,v.snapshot,envelope("late",v.body),System.currentTimeMillis()));}}
    @Test public void expiryAndMutationCannotExtendOrChangeTheNativeDisplayedReview()throws Exception{try(View v=new View()){var frozen=v.frozen();assertNull(RULES.current(frozen,v.frozenCatalogue,v.selected,4,v.snapshot,v.reply,v.body.getLong("expiresAt")));v.reply.getJSONObject("result").put("message","changed after display");assertNull(RULES.current(frozen,v.frozenCatalogue,v.selected,4,v.snapshot,v.reply,System.currentTimeMillis()));assertTrue(new JSONObject(frozen.getBody()).getString("message").contains("不运行程序"));}}
    @Test public void absentInstallationRaceRefusesBothUiConfirmationAndActualNativeInstallation()throws Exception{try(View v=new View()){var frozen=v.frozen();v.x.f.installEcho();JSONObject changed=v.x.owner.mcpSnapshot();assertFalse(RULES.targetCurrent(v.catalogue,changed));assertNull(RULES.current(frozen,v.frozenCatalogue,v.selected,4,changed,v.reply,System.currentTimeMillis()));assertThrows(SecurityException.class,()->v.x.owner.mcp("confirmLocalMcpInstall",new JSONObject().put("reviewId",v.body.getString("reviewId")).put("reviewDigest",v.body.getString("reviewDigest"))));}}
    @Test public void realPreviousInstallationRevisionZeroIsSupportedButFractionalOrReplacedRefsAreNot()throws Exception{try(View v=new View(true)){assertEquals(0,v.body.getLong("expectedStateRevision"));assertNotNull(v.frozen());JSONObject changed=new JSONObject(v.snapshot.toString());changed.getJSONArray("plugins").getJSONObject(0).put("stateRevision",0.5);assertFalse(RULES.targetCurrent(v.catalogue,changed));changed=new JSONObject(v.snapshot.toString());changed.getJSONArray("plugins").getJSONObject(0).put("installationId",UUID.randomUUID().toString());assertFalse(RULES.targetCurrent(v.catalogue,changed));}}
    @Test public void actualInstallationReceiptMustMatchDisplayedManifestAndRemainDisabledWithNoGrants()throws Exception{try(View v=new View()){var frozen=v.frozen();assertNotNull(frozen);String request=UUID.randomUUID().toString();var attempt=new McpLocalInstallAttempt(request,frozen);JSONObject result=v.x.owner.mcp("confirmLocalMcpInstall",RULES.confirmationPayload(frozen,v.frozenCatalogue,v.selected,4,v.snapshot,v.reply,System.currentTimeMillis()));assertNotNull(result.toString(),RULES.installed(attempt,envelope(request,result)));assertNull(RULES.installed(attempt,envelope("other",result)));for(String field:new String[]{"enabled","installationId"}){JSONObject changed=new JSONObject(result.toString()).put(field,field.equals("enabled")?true:"not-uuid");assertNull(RULES.installed(attempt,envelope(request,changed)));}JSONObject changed=new JSONObject(result.toString()).put("grants",new JSONArray().put("tool:lookup"));assertNull(RULES.installed(attempt,envelope(request,changed)));assertEquals(0,v.x.f.plugins.toolRegistry().length());assertEquals(1,v.x.f.tasks.list().length());}}
    @Test public void sourceChangeAfterCatalogueCannotBeHiddenByValidClientCorrelation()throws Exception{try(View v=new View()){assertNotNull(v.frozen());Files.write(v.x.f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(v.x.f.checkout).resolve("files/server.py"),"raise Exception('actual source drift')\n".getBytes(StandardCharsets.UTF_8));assertThrows(SecurityException.class,()->v.x.owner.mcp("confirmLocalMcpInstall",RULES.confirmationPayload(v.frozen(),v.frozenCatalogue,v.selected,4,v.snapshot,v.reply,System.currentTimeMillis())));assertEquals(0,v.x.f.plugins.snapshot().getJSONArray("plugins").length());assertEquals(0,v.x.f.runtime.environmentManager().describe(v.x.f.pack).getInt("activeLeases"));}}
    @Test public void changingNativeReviewAuthorityFlagsNeverTurnsItIntoALaunchOrToolGrant()throws Exception{try(View v=new View()){for(String field:new String[]{"programStarted","executionAuthorized","toolInvocationAuthorized","enabledAfterInstall","credentialsSupported","environmentInputsSupported","osSandbox"}){JSONObject body=new JSONObject(v.body.toString());body.remove("reviewDigest");body.put(field,true);body.put("reviewDigest",McpInstallPreviewRules.digest(body));assertNull(field,RULES.freeze(v.preparation,v.frozenCatalogue,v.selected,4,v.snapshot,envelope(v.request,body),System.currentTimeMillis()));}}}
    @Test public void nativeTaskApprovalDisclosureNamesTheActualProgramAndRiskWithoutPrivateArgvOrExtraPermission()throws Exception{try(var x=new McpLocalInvocationNativeTest.Fixture();var call=x.call()){JSONObject capability=call.capability();String text=McpLocalProgramApprovalText.describe(capability);assertNotNull(text);assertTrue(text.contains("python3"));assertTrue(text.contains("server.py"));assertTrue(text.contains("不是 OS 安全沙箱"));assertTrue(text.contains("不自动回写"));assertFalse(text.contains("--public-mode"));assertNull(McpLocalProgramApprovalText.describe(new JSONObject().put("feature","plugins").put("command","invoke")));assertNull(McpLocalProgramApprovalText.describe(new JSONObject(capability.toString()).put("command","other")));assertEquals(0,call.owner.f.tasks.get(call.task,false).getJSONArray("operations").length());}}
}
